struct Counter {
    var value = 0
    mutating func increment() { value += 1 }
}

mutating func append(_ x: Int) {
    if !isKnownUniquelyReferenced(&storage) {
        storage = storage.copy()
    }
    storage.items.append(x)
}

indirect enum Expr {
    case number(Int)
    case add(Expr, Expr)
}

